import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState<boolean | undefined>(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange)
  }, [])

  return !!isMobile
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

const config = {
  plugins: ["@tailwindcss/postcss"],
};

export default config;

content.text:
Nothing in the config is unusual. The remaining suspects are in my own code:

1. **`CardTitle` renders a `div`, and I put an `h2` inside it.** The nesting is valid, but I'll drop it and use a `div`/`h2` split that avoids any warning.
2. **`useSyncExternalStore` with `getSnapshot` reading `sessionStorage`.** The server snapshot is `""`. On hydration the client snapshot can differ, and React then re-renders with the client value. That is allowed, but it can log a hydration warning. A plain mounted flag is safer.
3. **`Select` with `value={undefined}`.** Switching between controlled and uncontrolled can log a warning, so I'll replace it with a stable controlled value.
4. **A lucide icon type import.** `LucideIcon` is exported by lucide-react 1.x, so I'll keep it.
5. **`aria-describedby` on `SelectTrigger`.** This is fine.

The Select's controlled/uncontrolled switch is the most likely console error. Radix `Select` accepts `value=""` to show the placeholder, so I'll pass a string consistently. I'll also read sessionStorage in a mount effect via a lazily initialised child, so there is no hydration mismatch.

